beforeSaveCustomScript:
name = string\trim(string\concatenate(firstName, ' ', lastName));
monthlyHours = ifThenElse(weeklyHours != null, number\round(weeklyHours * 4.33, 2), null);

$today = datetime\today();
$startOk = ifThenElse(startDate == null, true, startDate <= $today);
$endOk = ifThenElse(endDate == null, true, endDate >= $today);
status = ifThenElse($startOk && $endOk, 'Active', 'Inactive');
